fun countMultiples(lcm: Long, a: Int, b: Int): Int {
    val first = (a + lcm - 1) / lcm * lcm
    if (first > b) return 0
    val last = b / lcm * lcm
    return ((last - first) / lcm + 1).toInt()
}
